    if path is None:
        path = [start]
    if start == goal:
        return path
    if path[-1] not in graph:
        raise ValueError(f"Start node '{path[-1]}' is not a valid node in the graph")
    for neighbor in graph.get(path[-1], []):
        if neighbor not in path:
            new_path = find_path(graph, neighbor, goal, path + [neighbor])
            if new_path is not None:
                return new_path
    return None
