def find_path(graph, start, goal):
    # If the goal is the same as the start, we have a non-empty path
    if start == goal:
        return [start]  # The path by the given start and goal

    # Initialize the stack for the recursive and non-recursive search
    stack = [(start, [start])]
    visited = set()

    # Perform a depth-first search
    while stack:
        (node, path) = stack.pop()
        visited.add(node)
        for next_node in graph[node]:
            if next_node not in visited:
                if next_node == goal:
                    return path + [next_node]
                else:
                    stack.append((next_node, path + [next_node]))

    # If no path is found, return None
    return None
