def find_path(graph, start, goal, explored=None, path=None):
    if path is None:
        path = [start]
    if explored is None:
        explored = set()

    if start == goal:
        return path

    if not (type(start) is str) or type(goal) is not str:
        raise ValueError("Start and goal must be strings")

    if start not in graph:
        raise KeyError(f"Start node {start} not found in the graph")

    if goal not in graph:
        raise KeyError(f"Goal node {goal} not found in the graph")

    if start in explored:
        return None

    explored.add(start)

    neighbors = graph.get(start, [])
    for neighbor in neighbors:
        if neighbor not in explored:
            new_path = find_path(graph, neighbor, goal, explored, path + [neighbor])
            if new_path is not None:
                return new_path

    return None
