def find_path(graph, start, goal):
    # A stack (using a list) for the recursive and a set for the visited nodes
    recurse_stack = [start]
    visited = set()

    # Recursive helper function to find the path
    def explore_recursive (current, goal, recurse_stack, visited):
        visited.add(current)
        if current == goal:
            return [current]
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                result = explore_recursive(neighbor, goal, recurse_stack, visited)
                if result:
                    return [current] + result
        return None

    # Start the recursive search
    result = explore_recursive(start, goal, recurse_stack, visited)

    return result
