def find_path(graph, start, goal):
    if start is None or goal is None:
        raise ValueError('Both start and goal cannot be None')  # Ensure both are not None

    if not (start in graph and goal in graph):
        raise ValueError('Start or goal is not a valid node in the graph')

    visited = set()
    path_stack = [(start, [start])]  # (current_node, path)

    while path_stack:
        current_node, path = path_stack.pop()
        visited.add(current_node)

        if current_node == goal:
            return path

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                new_path = path + [neighbor]
                path_stack.append((neighbor, new_path))

    return None  # Goal is unreachable
