def find_path(graph, start, goal):
    if start is None or goal is None:
        raise ValueError("Start and goal cannot be None')

    if start not in graph:
        raise ValueError(f'Given a non-existing start node: non empty and non None')

    if goal not in graph:
        raise ValueError(f'Given a non-existing goal node: non empty and non None')

    if start == goal:
        return [start]

    visited = set()
    path = []
    stack = [[start]]

    while stack:
        path = stack.pop()
        node = path[-1]

        if node not in visited:
            visited.add(node)
            if node == goal:
                path.insert(0, goal)
                return path

            for neighbor in graph.get(node, []):
                new_path = path.copy()
                new_path.append(neighbor)
                stack.append(new_path)

    return None
