def find_path(graph, start, goal, path=None):
    if path is None:
        path = [start]
    if path[-1] == goal:
        return path
    if path[-1] not in graph:
        return None
    if path[-1] not in graph.keys():
        return None
    neighbors = graph.get(path[-1])
    if neighbors is None:
        return None
    for neighbor in neighbors:
        if neighbor not in path:
            new_path = find_path(graph, neighbor, goal, path + [neighbor])
            if new_path is not None:
                return new_path
    return None

